<?php if(!session()->has('form_started'))session()->put('form_started',time());$form_values=$form_values??[];$form_errors=$form_errors??[];?>
<section class="section-padding" id="quote"><div class="container"><div class="row g-4"><div class="col-lg-5 reveal"><div class="contact-info-card"><h3><i class="fa-solid fa-building me-2"></i><?=text('contact_information')?></h3><?php foreach(['address'=>['our_address','location-dot'],'phone'=>['phone','phone'],'email'=>['email','envelope']] as $key=>[$label,$icon]):if(!setting($key))continue;?><div class="ci-item"><div class="ci-icon"><i class="fa-solid fa-<?=$icon?>"></i></div><div><h6><?=text($label)?></h6><?php if($key==='address'&&setting('map_link')):?><a class="contact-map-link" href="<?=e(cms_url(setting('map_link')))?>" target="_blank" rel="noopener noreferrer"><?=nl2br(e(setting($key)))?></a><?php else:?><p><?=nl2br(e(setting($key)))?></p><?php endif?></div></div><?php endforeach?><?php if(setting('business_hours')):?><div class="ci-item"><div class="ci-icon"><i class="fa-regular fa-clock"></i></div><p><?=nl2br(e(setting('business_hours')))?></p></div><?php endif?><?php if(setting('map_embed')):?><div class="contact-map-frame"><iframe title="<?=text('our_address')?>" src="<?=e(setting('map_embed'))?>" loading="lazy" referrerpolicy="no-referrer-when-downgrade"></iframe></div><?php endif?></div></div><div class="col-lg-7 reveal"><div class="contact-form-card" id="contact-form-card"><h3 class="mb-2"><?=e(($section['heading']??'')?:setting('text.contact_title'))?></h3><p><?=e(($section['description']??'')?:setting('text.contact_intro'))?></p><?php if($form_errors):?><div class="alert alert-danger" role="alert"><strong><?=text('quote_error')?></strong><ul><?php foreach($form_errors as $key=>$error):?><li><?=e($error)?></li><?php endforeach?></ul></div><?php endif?><form method="post" action="<?=e(cms_url('/enquiry/'))?>" data-quote-form data-sending="<?=text('sending')?>" data-security-check="<?=text('security_check')?>"><?=csrf_field()?><div hidden aria-hidden="true"><label>Leave this empty<input name="website_url" tabindex="-1" autocomplete="off"></label></div><div class="row g-3"><?php foreach(['name','phone','email','company','requirement','message'] as $key):$required=in_array($key,['name','email','message'],true);?><div class="<?=in_array($key,['requirement','message'],true)?'col-12':'col-md-6'?>"><label for="enquiry-<?=$key?>" class="visually-hidden"><?=text('field_'.$key)?></label><?php if($key==='message'):?><textarea id="enquiry-<?=$key?>" class="form-control" name="message" placeholder="<?=text('field_message')?>" rows="4" maxlength="10000" required><?=e($form_values[$key]??'')?></textarea><?php else:?><input id="enquiry-<?=$key?>" class="form-control" name="<?=$key?>" type="<?=$key==='email'?'email':'text'?>" value="<?=e($form_values[$key]??'')?>" placeholder="<?=text('field_'.$key)?>" maxlength="<?=$key==='phone'?50:255?>" <?=$required?'required':''?>><?php endif?></div><?php endforeach?><?php if(setting('turnstile_site_key')):?><div class="col-12"><div class="cf-turnstile" data-sitekey="<?=e(setting('turnstile_site_key'))?>" data-action="quote"></div></div><?php endif?><div class="col-12"><small><?=text('privacy_notice')?></small></div><div class="col-12"><button class="btn-submit" type="submit"><span class="spinner-border spinner-border-sm me-2" data-quote-spinner hidden aria-hidden="true"></span><span data-quote-label><?=text('submit_enquiry')?></span></button><span class="visually-hidden" data-quote-status role="status" aria-live="polite"></span></div></div></form></div></div></div></div></section>
